# Manim kit gallery: every component in short sections (rendered by tests/render_manim_gallery.py, no LLM).
# Each section ends with self.wait(1.0) so a still can be grabbed; section boundaries are logged as "SECTION <name> <t>".
class Seg(Scene):
    def tag(self, text):
        """Component names in the caption band, so the showreel says what you're looking at."""
        t = Text(text, font_size=26, color=MUTED, font="Noto Sans Mono", weight=BOLD)
        if t.width > 8:
            t.scale_to_fit_width(8)
        t.move_to([0, -5.6, 0])
        self.add(t)

    def snap(self, name):
        print(f"SECTION {name} {self.renderer.time:.2f}")
        self.wait(1.0)
        self.play(*[FadeOut(m) for m in self.mobjects], run_time=0.3)

    def construct(self):
        # 1 general: title, icons, callout, pills, arrow
        self.tag("KTitle · Icon · LabeledArrow · Pill · Callout")
        t = KTitle("Why HTTPS matters", kicker="networking")
        icons = VGroup(Icon("Laptop", label="You"), Icon("Lock", color=ACCENT3, label="TLS"), Icon("Server", label="Bank")).arrange(RIGHT, buff=0.7)
        place(icons, "main")
        arrow = LabeledArrow(icons[0].get_bottom() + DOWN * 0.3, icons[2].get_bottom() + DOWN * 0.3, "encrypted", GOOD, side=DOWN)
        pills = VGroup(Pill("AES-256"), Pill("RSA", ACCENT2)).arrange(RIGHT, buff=0.3)
        place(pills, "below")
        self.play(Write(t), LaggedStart(*[FadeIn(i, scale=0.7) for i in icons], lag_ratio=0.2))
        call = Callout("nobody can read it").next_to(icons, UP, buff=0.4)
        self.play(GrowArrow(arrow[0]), FadeIn(arrow[1]), FadeIn(pills), FadeIn(call, shift=DOWN * 0.2))
        self.snap("general")

        # 2 general: steps, bars, counter, split, timeline
        self.tag("StepList")
        steps = StepList(["Sort the array", "Walk two pointers", "Stop when they meet"]).place("main")
        self.play(FadeIn(steps))
        self.play(steps.activate(1))
        self.snap("steps")
        self.tag("HBarChart · Counter")
        chart = HBarChart([("scan", 12), ("binary", 48), ("hash", 95)], unit="M").place("main")
        c = Counter(0, unit="M/s", label="hash map").place("below")
        self.play(chart.grow(), FadeIn(c))
        self.play(chart.highlight(2), c.count_to(95), run_time=1)
        self.snap("chart")
        self.tag("Split · Timeline")
        sp = place(Split("Brute force", "check every pair\nO(n²)", "Hash map", "one pass\nO(n)"), "main")
        tl = place(Timeline(["1958 · hashing", "1972 · B-trees", "2009 · Redis"]), "below")
        self.play(FadeIn(sp))
        self.play(LaggedStart(*[FadeIn(m) for m in tl], lag_ratio=0.25))
        self.snap("split")

        # 3 array: two pointers + window + swap + note
        self.tag("MArray · pointer · window · note · MVarWatch")
        t = KTitle("Two pointers", kicker="LeetCode 167")
        arr = MArray([1, 2, 4, 5, 7, 11], label="numbers").place()
        vw = MVarWatch({"target": 9, "sum": 12}).place("below")
        self.play(Write(t), Create(arr), FadeIn(vw))
        self.play(arr.pointer("l", 0), arr.pointer("r", 5), arr.mark({0: "compare", 5: "compare"}), arr.note("1 + 11 = 12 > 9"))
        self.play(arr.pointer("r", 4), arr.mark({5: "dim", 4: "compare"}), arr.note("1 + 7 = 8 < 9"), vw.set("sum", 8))
        self.play(arr.pointer("l", 1), arr.mark({0: "dim", 1: "compare"}), arr.note("2 + 7 = 9"), vw.set("sum", 9))
        self.play(arr.window(1, 4), arr.mark({1: "found", 4: "found"}))
        self.snap("array")
        self.tag("MString · swap")
        s = MString("abcabcbb", label="s").place()
        self.play(Create(s))
        self.play(s.pointer("L", 0), s.pointer("R", 2), s.window(0, 2))
        self.play(s.swap(0, 1), s.note("swap demo"))
        self.snap("string")

        # 4 grid DP
        self.tag("MGrid · fill · active · deps")
        t = KTitle("Edit distance DP")
        dp = MGrid([[None] * 4 for _ in range(4)], row_labels=["", "c", "a", "t"], col_labels=["", "c", "u", "t"]).place()
        self.play(Write(t), FadeIn(dp))
        self.play(dp.fill([(0, 0, 0), (0, 1, 1), (0, 2, 2), (0, 3, 3), (1, 0, 1), (2, 0, 2), (3, 0, 3)]))
        self.play(dp.set(1, 1, 0), dp.active(1, 1), dp.deps(1, 1, [(0, 0)]))
        self.play(dp.fill([(1, 2, 1), (1, 3, 2), (2, 1, 1), (2, 2, 1), (2, 3, 2), (3, 1, 2), (3, 2, 2), (3, 3, 1)]), dp.active(3, 3), dp.deps(3, 3, [(2, 2), (2, 3), (3, 2)]))
        self.play(dp.mark({(3, 3): "found"}))
        self.snap("grid")

        # 5 linked list reversal
        self.tag("MLinkedList · relink · pointer")
        t = KTitle("Reverse a linked list")
        ll = MLinkedList([1, 2, 3, 4]).place()
        self.play(Write(t), FadeIn(ll))
        self.play(ll.pointer("prev", None), ll.pointer("curr", 0))
        self.play(ll.relink(0, None), ll.pointer("prev", 0), ll.pointer("curr", 1), ll.mark({0: "done"}))
        self.play(ll.relink(1, 0), ll.pointer("prev", 1), ll.pointer("curr", 2), ll.mark({1: "done"}))
        self.play(ll.relink(2, 1), ll.relink(3, 2), ll.pointer("prev", 3), ll.mark({2: "done", 3: "found"}))
        self.snap("list")

        # 6 stack, queue, map
        self.tag("MStack · MHashMap · MQueue")
        st = MStack(["("], capacity=4)
        hm = MHashMap(label="count")
        VGroup(st, hm).arrange(RIGHT, buff=0.9, aligned_edge=DOWN)
        place(VGroup(st, hm), "main")
        q = MQueue([1, 2, 3], capacity=6).place("below")
        self.play(FadeIn(st), FadeIn(hm), FadeIn(q))
        self.play(st.push("["), hm.put("a", 1), q.enqueue(4))
        self.play(st.pop(), hm.put("b", 1), q.dequeue())
        self.play(st.push("{", "active"), hm.put("a", 2), hm.get("a"))
        self.snap("stack_queue_map")

        # 7 binary tree
        self.tag("MBinaryTree · visit · badge · mark_edge")
        t = KTitle("Maximum depth", kicker="LeetCode 104")
        tree = MBinaryTree([3, 9, 20, None, None, 15, 7]).place()
        self.play(Write(t), FadeIn(tree))
        self.play(tree.active("0"))
        self.play(tree.visit("1"), tree.badge("1", "1"), tree.active("1"))
        self.play(tree.visit("5"), tree.visit("6"), tree.badge("5", "1"), tree.badge("6", "1"))
        self.play(tree.badge("2", "2"), tree.mark_edge("2"), tree.mark_edge("5"), tree.badge("0", "3"), tree.mark({"0": "found"}), tree.active("0"))
        self.snap("tree")

        # 8 graph BFS
        self.tag("MGraph · mark · mark_edge · badge")
        t = KTitle("Breadth-first search")
        g = MGraph({"A": (0, 2.2), "B": (-2, 0.6), "C": (2, 0.6), "D": (-2.8, -1.4), "E": (0, -1.4), "F": (2.8, -1.4)},
                   [("A", "B", 4), ("A", "C", 1), ("B", "D", 2), ("B", "E", 5), ("C", "E", 8), ("C", "F", 3)]).place()
        self.play(Write(t), FadeIn(g))
        self.play(g.mark({"A": "active"}), g.badge("A", "0"))
        self.play(g.mark({"A": "done", "B": "frontier", "C": "frontier"}), g.mark_edge("A", "B"), g.mark_edge("A", "C"), g.badge("B", "1"), g.badge("C", "1"))
        self.snap("graph")

        # 9 heap + trie + recursion
        self.tag("MHeap · swap")
        h = MHeap([1, 3, 2, 7, 5, 4, 9, 0]).place()
        self.play(FadeIn(h), h.mark({7: "active"}))
        self.play(h.swap(7, 3))
        self.play(h.swap(3, 1))
        self.play(h.swap(1, 0), h.mark({0: "found"}))
        self.snap("heap")
        self.tag("MTrie")
        tr = MTrie(["cat", "car", "cart", "dog", "do"]).place()
        self.play(FadeIn(tr))
        self.play(tr.mark({"c": "path", "ca": "path", "car": "path", "cart": "found"}), tr.mark_edge("c"), tr.mark_edge("ca"), tr.mark_edge("car"), tr.mark_edge("cart"))
        self.snap("trie")
        self.tag("MRecursionTree")
        rt = MRecursionTree(("f(4)", [("f(3)", [("f(2)", [("f(1)",), ("f(0)",)]), ("f(1)",)]), ("f(2)", [("f(1)",), ("f(0)",)])])).place()
        self.play(FadeIn(rt))
        self.play(rt.badge("0.0", "2"), rt.mark({"0.1": "visited"}), rt.badge("0.1", "memo"), rt.badge("0", "3"), rt.mark({"0": "found"}))
        self.snap("recursion")

        # 10 intervals, code, problem card, complexity
        self.tag("MIntervals · merged · sweep")
        iv = MIntervals([(1, 3), (2, 6), (8, 10), (15, 18)]).place()
        self.play(FadeIn(iv), iv.sweep(2), iv.mark({0: "compare", 1: "compare"}))
        self.play(iv.merged([(1, 6), (8, 10), (15, 18)]), iv.mark({0: "done", 1: "done", 2: "done", 3: "done"}), iv.sweep(18))
        self.snap("intervals")
        self.tag("ProblemCard")
        card = place(ProblemCard("Two Sum", "Easy", 1, ["Array", "Hash Table"], "nums = [2,7,11,15], target = 9", "[0,1]"), "main")
        self.play(FadeIn(card, shift=UP * 0.3))
        self.snap("problem")
        self.tag("MCode · highlight · Complexity")
        code = MCode("def twoSum(nums, target):\n    seen = {}\n    for i, x in enumerate(nums):\n        if target - x in seen:\n            return [seen[target - x], i]\n        seen[x] = i").place("main")
        cx = place(Complexity("O(n)", "O(n)", was="O(n²)"), "below")
        self.play(FadeIn(code))
        self.play(code.highlight(3))
        self.play(code.highlight(4, 5), FadeIn(cx))
        self.snap("code")
